  2	import * as path from 'node:path';
  3	import { getWorkspaceFilePath } from './vscode-workspace.js';
  4	import type { ErrorLogManager } from '../error-log/error-log.manager.js';
  5	
  6	export interface WorkspaceHealthIssue {
  7	    type: string;
  8	    severity: 'error' | 'warning';
  9	    message: string;
 10	    fixAction: string;
 11	    repositoryId?: string;
 12	}
 13	
 14	export interface WorkspaceHealthReport {
 15	    healthy: boolean;
 16	    issues: WorkspaceHealthIssue[];
 17	}
 18	
 19	/**
 20	 * Performs a side-effect-free health check on a workspace.
 21	 *
 22	 * Checks:
 23	 * 1. Whether the VS Code .code-workspace file exists on disk.
 24	 * 2. Whether each repository directory contains a `.git` entry
 25	 *    (i.e. has been successfully cloned).
 26	 * 3. (Optional) Whether the error log contains recent credential-missing entries
 27	 *    for repositories in this workspace. Only performed when `errorLogManager`
 28	 *    is provided.
 29	 *
 30	 * Note on `.git` detection: the clone check uses `fs.existsSync` on the `.git`
 31	 * path entry, which returns `true` for both a `.git` directory (standard clone)
 32	 * and a `.git` file (git worktree pointer). Both forms are treated as a
 33	 * successfully cloned repository. If you need to distinguish between a full
 34	 * clone and a worktree, use `fs.statSync().isDirectory()` instead.
 35	 *
 36	 * @param projectId       Project identifier (used as the project slug in paths).
 37	 * @param workspaceId     Workspace identifier.
 38	 * @param projectsFolder  Root folder where projects are stored on disk.
 39	 * @param repositoryIds   Ordered list of repository IDs belonging to the workspace.
 40	 * @param errorLogManager Optional error log manager. When provided, the health
 41	 *                        report includes `credential-missing` issues for repositories
 42	 *                        whose most recent setup run logged a credential error.
 43	 * @returns               A health report with a `healthy` flag and an array of issues.
 44	 */
 45	export function checkWorkspaceHealth(
 46	    projectId: string,
 47	    workspaceId: string,
 48	    projectsFolder: string,
 49	    repositoryIds: string[],
 50	    errorLogManager?: ErrorLogManager,
 51	): WorkspaceHealthReport {
 52	    const issues: WorkspaceHealthIssue[] = [];
 53	
 54	    // Check 1: VS Code workspace file exists.
 55	    const workspaceFilePath = getWorkspaceFilePath(projectsFolder, projectId, workspaceId);
 56	    if (!fs.existsSync(workspaceFilePath)) {
 57	        issues.push({
 58	            type: 'workspace-file-missing',
 59	            severity: 'warning',
 60	            message: 'VS Code workspace file is missing.',
 61	            fixAction: 'regenerate-workspace-file',
 62	        });
 63	    }
 64	
 65	    // Check 2: Each repository has been cloned (has a .git subdirectory).
 66	    for (const repoId of repositoryIds) {
 67	        const repoPath = path.join(projectsFolder, projectId, workspaceId, repoId);
 68	        if (!fs.existsSync(path.join(repoPath, '.git'))) {
 69	            issues.push({
 70	                type: 'repository-not-cloned',
 71	                severity: 'warning',
 72	                message: `Repository "${repoId}" is not cloned.`,
 73	                fixAction: 'setup-workspace',
 74	                repositoryId: repoId,
 75	            });
 76	        }
 77	    }
 78	
 79	    // Check 3: (Optional) Credential-missing errors from the most recent setup run.
 80	    // Query all credential error entries for this workspace and surface the most
 81	    // recent entry per repository as a health issue. Only repos whose entry is from
 82	    // the most recent setup invocation (i.e. the entry with the highest Id) are
 83	    // included — this avoids surfacing stale errors from prior setup runs.
 84	    if (errorLogManager) {
 85	        const { entries } = errorLogManager.list({ source: 'credentials' });
 86	
 87	        // Filter to entries scoped to this workspace.
 88	        const wsEntries = entries.filter(
 89	            (e) =>
 90	                e.Context.WorkspaceId === workspaceId &&
 91	                e.Context.ProjectId === projectId &&
 92	                e.Context.RepositoryId !== undefined,
 93	        );
 94	
 95	        // De-duplicate by repository ID, keeping only the most recent entry per repo
 96	        // (entries are returned newest-first from errorLogManager.list()).
 97	        const seenRepos = new Set<string>();
 98	        for (const entry of wsEntries) {
 99	            const repoId = entry.Context.RepositoryId!;
100	            if (!seenRepos.has(repoId)) {

