 58	 */
 59	function wsFilePath(projectsFolder: string, projectId: string, workspaceId: string): string {
 60	    return path.join(projectsFolder, projectId, `${projectId}-${workspaceId}.code-workspace`);
 61	}
 62	
 63	/** Create the `.code-workspace` file on disk (parent dirs created if needed). */
 64	function createWsFile(projectsFolder: string, projectId: string, workspaceId: string): void {
 65	    const p = wsFilePath(projectsFolder, projectId, workspaceId);
 66	    fs.mkdirSync(path.dirname(p), { recursive: true });
 67	    fs.writeFileSync(p, JSON.stringify({ folders: [] }));
 68	}
