 70	/** Create a `.git` directory inside the repo path (simulates a cloned repo). */
 71	function createRepoDotGit(
 72	    projectsFolder: string,
 73	    projectId: string,
 74	    workspaceId: string,
 75	    repoId: string,
 76	): void {
